#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.graveWarden_State)]
    public class GraveWarden_StateBehaviour : EnemyStateBehaviour
    {
        public GraveWarden_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override int GetActiveState(Entity enemy)
        {
            if (GraveWarden.CanPlaceGrave(enemy))
            {
                return GraveWarden.STATE_PLACE;
            }
            return base.GetActiveState(enemy);
        }
    }
}
